'use strict';
// Two languages. Russian is the source: every UI string in app.js is written in Russian and wrapped in
// t('…'); this file maps it to English. `{name}` placeholders are filled from the second argument.
//
// Texts the server recorded into runs (step titles, details, errors, lint messages) are Russian too and
// go through tt(): first the exact map, then the pattern list below, otherwise unchanged — so old runs
// read in English as well, and a phrase without a pattern simply stays Russian.
// Since 2026-11-09 the server records English (describe(), details, errors, lint): TT_RU below turns those into
// Russian, TT keeps the older Russian runs readable in English. Works in Node too (CLI): LANG from E2E_LANG.
const LANG = (() => {
  if (typeof localStorage === 'undefined') return typeof process !== 'undefined' && process.env && process.env.E2E_LANG === 'ru' ? 'ru' : 'en';
  // the choice made with the header switch wins; before any choice the interface follows the browser language
  const browser = typeof navigator !== 'undefined' && /^ru/i.test(navigator.language || '') ? 'ru' : 'en';
  try { const saved = localStorage.getItem('e2e.lang'); return saved === 'en' || saved === 'ru' ? saved : browser; } catch { return browser; }
})();
const LOCALE = LANG === 'en' ? 'en-GB' : 'ru-RU';
if (typeof document !== 'undefined') document.documentElement.lang = LANG;

