// Recorded server texts: patterns over the Russian originals (lib/runner.js describe(), details, errors, lint).
const TT = [
  [/^Нажать «(.*)» \(если есть\)$/s, 'Tap "$1" (if present)'], [/^Дважды нажать «(.*)»$/s, 'Double-tap "$1"'], [/^Нажать «(.*)»$/s, 'Tap "$1"'],
  [/^Ввести «(.*)» в «(.*)»$/s, 'Type "$1" into "$2"'], [/^Ввести «(.*)»$/s, 'Type "$1"'], [/^Открыть (\S+)$/, 'Open $1'],
  [/^(Быстро пролистать|Пролистать) (вверх|вниз)( ×\d+)?( «.*»)?$/s, (m, f, d, n, tg) => `${f === 'Быстро пролистать' ? 'Fling' : 'Swipe'} ${d === 'вверх' ? 'up' : 'down'}${n || ''}${tg ? tg.replace(/«(.*)»/, '"$1"') : ''}`],
  [/^(Быстро смахнуть|Смахнуть) (влево|вправо)( ×\d+)?( «.*»)?$/s, (m, f, d, n, tg) => `${f === 'Быстро смахнуть' ? 'Fling row' : 'Swipe row'} ${d === 'влево' ? 'left' : 'right'}${n || ''}${tg ? tg.replace(/«(.*)»/, '"$1"') : ''}`],
  [/^Подождать (\S+) с$/, 'Wait $1 s'], [/^На экране (\d+) × (.*)$/s, 'On screen: $1 × $2'], [/^На экране нет (.*)$/s, 'Not on screen: $1'], [/^На экране есть (.*)$/s, 'On screen: $1'],
  [/^элемент (.*)$/s, 'element $1'], [/^текст по шаблону (.*)$/s, 'text matching $1'], [/^Экран как эталон «(.*)»$/s, 'Screen equals baseline "$1"'],
  [/^Повторять, пока не (.*)$/s, 'Repeat until $1'], [/^Повторить (\d+) раз(.*)$/s, 'Repeat $1 times$2'], [/\((\d+) шаг\.\)$/, '($1 steps)'],
  [/^не ((?:на экране|нет|есть) .*)$/s, (m, r) => 'not ' + tt(r)], [/^на экране «(.*)»$/s, '"$1" on screen'], [/^нет «(.*)»$/s, 'no "$1"'], [/^если (.*)$/s, 'if $1'], [/^иначе: (.*)$/s, 'else: $1'], [/^есть (.*)$/s, '$1 is set'],
  [/^нажал в \((\d+), (\d+)\)$/, 'tapped at ($1, $2)'], [/^(холодный старт|старт) (\d+) мс$/, (m, k, ms) => `${k === 'старт' ? 'start' : 'cold start'} ${ms} ms`],
  [/^прошёл с (\d+)-й попытки( \(flaky\))?$/, 'passed on attempt $1$2'], [/^необязательный шаг не прошёл: (.*)$/s, 'optional step failed: $1'],
  [/^(резких )?свайпов подряд: (\d+), пауза (\d+) мс$/, (m, f, n, p) => `${f ? 'flings' : 'swipes'} in a row: ${n}, pause ${p} ms`], [/^найдено (\d+)$/, 'found $1'],
  [/^повторил (\d+) раз$/, 'repeated $1 times'], [/^условие выполнилось после (\d+) повтор\.$/, 'condition held after $1 repeats'],
  [/^эталона «(.*)» ещё не было — сохранил этот экран как эталон$/s, 'no baseline "$1" yet — saved this screen as the baseline'], [/^совпадает с эталоном «(.*)», расхождение (.*)%$/s, 'matches baseline "$1", mismatch $2%'],
  [/^«(.*)» не появилось — пропустил$/s, '"$1" did not appear — skipped'], [/^«(.*)» нет в дереве экрана — нажал по координатам \((.*)\)$/s, '"$1" is not in the screen tree — tapped at ($2)'],
  [/^не нашёл на экране «(.*)»$/s, 'could not find "$1" on screen'], [/^на экране: (.*)$/s, 'on screen: $1'], [/^ждал на экране «(.*)»$/s, 'waited for "$1" on screen'], [/^на экране всё ещё есть «(.*)»$/s, '"$1" is still on screen'],
  [/^на экране (\d+) × «(.*)», ждал (\d+)$/s, 'on screen $1 × "$2", expected $3'], [/^не нашёл поле «(.*)»$/s, 'could not find field "$1"'], [/^не нашёл строку «(.*)» для свайпа$/s, 'could not find row "$1" to swipe'],
  [/^экран отличается от эталона «(.*)» на (.*)% \(порог (.*)%\)$/s, 'screen differs from baseline "$1" by $2% (threshold $3%)'], [/^размер экрана (.*) не совпадает с эталоном (.*)$/s, 'screen size $1 does not match the baseline $2'],
  [/^за (\d+) повторов так и не стало: (.*)$/s, 'after $1 repeats still not: $2'], [/^Android: приложение не отвечало \(ANR\) (\d+) раз, консоль нажала «Подождать»$/, 'Android: the app was not responding (ANR) $1 time(s), the console pressed "Wait"'],
  [/^правило noServerErrors: приложение получило 5xx — (.*)$/s, 'rule noServerErrors: the app received 5xx — $1'], [/^шаг (\d+): (.*)$/s, (m, n, rest) => `step ${n}: ${tt(rest)}`], [/^скриншот не снят: (.*)$/s, 'screenshot not taken: $1'],
  [/^нет токена роли «(.*)»: .*$/s, 'no token for role "$1": add it in Settings (accounts) — a token, or a phone for the login plugin'],
  [/^сценарий не собрался: (.*)$/s, 'the scenario did not compile: $1'], [/^замер пока только на Android$/, 'measurement is Android-only for now'],
  [/^замер (\d+)\/(\d+)$/, 'measurement $1/$2'], [/^Эмулятор$/, 'Emulator'],
  // lint
  [/^поле сценария «(.*)» ничего не делает$/s, 'scenario field "$1" does nothing'], [/^(.*): переменная «(.*)» нигде не задана .*$/s, (m, where, v) => `${tt(where)}: variable "${v}" is not defined anywhere (settings, scenario vars, save or matrix)`],
  [/^(.*): параметр блока «(.*)» не передан через with и не является переменной$/s, (m, where, v) => `${tt(where)}: block parameter "${v}" is not passed via with and is not a variable`], [/^(.*)блок «(.*)» не найден$/s, (m, pre, b) => `${tt(pre)}block "${b}" not found`],
  [/^(.*): в последнем прогоне в ответе не было поля «(.*)»$/s, (m, where, f) => `${tt(where)}: the last run's response had no field "${f}"`], [/^в сценарии нет шагов$/, 'the scenario has no steps'], [/^у сценария нет названия$/, 'the scenario has no name'],
  [/^(.*?)шаг (\d+)( \(блок (.*?)\))?(.*)$/s, (m, pre, n, blk, name, rest) => `${pre}step ${n}${blk ? ` (block ${name})` : ''}${rest}`]
];

