function t(key, vars) {
  let s = LANG === 'en' ? (EN[key] ?? key) : key;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.split(`{${k}}`).join(String(v));
  return s;
}
// recorded texts: exact map → patterns → composite labels; untranslatable text comes back unchanged
function tt(text) {
  if (text == null || text === '') return text;
  const s = String(text);
  const map = LANG === 'en' ? EN : RU;
  const pats = LANG === 'en' ? TT : TT_RU;
  const quotes = LANG === 'en' ? (x) => x.replace(/«([^»]*)»/g, '"$1"') : (x) => x.replace(/"([^"\n]*)"/g, '«$1»');
  if (map[s]) return map[s];
  if (s.includes('\n')) return s.split('\n').map((line) => tt(line)).join('\n');
  for (const [re, rep] of pats) if (re.test(s)) return quotes(s.replace(re, rep));
  for (const sep of [' — ', ' · ']) {
    if (!s.includes(sep)) continue;
    const parts = s.split(sep);
    const out = parts.map((p) => (p.includes(' — ') || p.includes(' · ') ? tt(p) : (map[p] || pats.reduce((acc, [re, rep]) => (acc === null && re.test(p) ? quotes(p.replace(re, rep)) : acc), null) || p)));
    if (out.some((p, i) => p !== parts[i])) return out.join(sep);
  }
  return s;
}
